import java.util.Scanner;

public class Main {
    static final int MAXN = 500;
    static int[][] C = new int[MAXN + 1][MAXN + 1];
    static Pair[] dp1s = new Pair[MAXN + 1];
    static Pair[][][] dp2s = new Pair[2][MAXN + 1][MAXN + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void inc(long[] a, long b, int mod) {
        a[0] += b;
        if (a[0] >= mod) a[0] -= mod;
    }

    static long sumN(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        for (int i = 0; i <= m; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
                if (C[i][j] >= mod) C[i][j] -= mod;
            }
        }

        for (int i = 0; i <= m; ++i) {
            dp1s[i] = new Pair();
        }
        dp1s[0].first = 1;

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= i; ++j) {
                long w = (dp1s[j - 1].first * dp1s[i - j].first) % mod * C[i - 1][j - 1] % mod;
                long[] secondVal = {0};
                inc(secondVal, (sumN(j - 1) + sumN(i - j)) * w % mod, mod);
                inc(secondVal, (dp1s[j - 1].second * dp1s[i - j].first) % mod * (i + 1) % mod * C[i - 1][j - 1], mod);
                inc(secondVal, (dp1s[j - 1].first * dp1s[i - j].second) % mod * (i + 1) % mod * C[i - 1][j - 1], mod);
                dp1s[i].second = (dp1s[i].second + secondVal[0]) % mod;
                dp1s[i].first = (dp1s[i].first + w * (i + 1)) % mod;
            }
        }

        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j <= n; ++j) {
                for (int k = 0; k <= m; ++k) {
                    dp2s[i][j][k] = new Pair();
                }
            }
        }

        dp2s[0][0][0].first = 1;
        dp2s[1][0][0].first = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                for (int ln = 1; ln <= n - i; ++ln) {
                    // Update dp2s[1][i + ln][j]
                    inc(new long[]{dp2s[1][i + ln][j].first}, dp2s[0][i][j].first, mod);
                    inc(new long[]{dp2s[1][i + ln][j].second}, dp2s[0][i][j].second, mod);

                    // Update dp2s[0][i + ln][j + ln]
                    long val1 = (dp2s[1][i][j].first * dp1s[ln].first) % mod * C[j + ln][j] % mod;
                    inc(new long[]{dp2s[0][i + ln][j + ln].first}, val1, mod);

                    long val2 = (dp2s[1][i][j].first * dp1s[ln].second) % mod * C[j + ln][j] % mod;
                    inc(new long[]{dp2s[0][i + ln][j + ln].second}, val2, mod);

                    long val3 = (dp2s[1][i][j].second * dp1s[ln].first) % mod * C[j + ln][j] % mod;
                    inc(new long[]{dp2s[0][i + ln][j + ln].second}, val3, mod);
                }
            }
        }

        long final_ans = (dp2s[0][n][m].second + dp2s[1][n][m].second) % mod;
        System.out.println(final_ans);
        sc.close();
    }
}
